<?php $admin_title='Batch & Expiry Tracking';include '_header.php';$pdo->exec("CREATE TABLE IF NOT EXISTS stock_batches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id INT UNSIGNED NOT NULL,batch_no VARCHAR(100) NOT NULL,quantity INT NOT NULL DEFAULT 0,expiry_date DATE NULL,received_date DATE NULL,notes VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_batch_expiry(expiry_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_ok($_POST['csrf']??''))$msg='Security token expired.';else{try{$pid=(int)($_POST['product_id']??0);$batch=trim($_POST['batch_no']??'');$qty=(int)($_POST['quantity']??0);$expiry=$_POST['expiry_date']?:null;$received=$_POST['received_date']?:date('Y-m-d');if(!$pid||$batch===''||$qty<1)throw new Exception('Product, batch number and positive quantity are required.');$q=$pdo->prepare('INSERT INTO stock_batches(product_id,batch_no,quantity,expiry_date,received_date,notes) VALUES(?,?,?,?,?,?)');$q->execute([$pid,$batch,$qty,$expiry,$received,trim($_POST['notes']??'')]);$msg='Batch details saved. Note: batch quantity is informational; use Stock In to change total inventory.';}catch(Throwable $e){$msg=$e->getMessage();}}}$products=$pdo->query("SELECT id,name,sku FROM products WHERE status='active' ORDER BY name")->fetchAll();$rows=$pdo->query('SELECT b.*,p.name product_name,p.sku FROM stock_batches b JOIN products p ON p.id=b.product_id ORDER BY b.expiry_date IS NULL,b.expiry_date ASC LIMIT 300')->fetchAll();?><?php if($msg):?><div class="panel"><b><?=e($msg)?></b></div><?php endif;?><div class="panel"><div class="panel-head"><h2>Register Product Batch</h2></div><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><div class="form-grid"><div class="form-group"><label>Product *</label><select class="form-control" name="product_id" required><option value="">Choose product</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?> (<?=e($x['sku'])?>)</option><?php endforeach;?></select></div><div class="form-group"><label>Batch / Lot Number *</label><input class="form-control" name="batch_no" required></div><div class="form-group"><label>Batch quantity *</label><input class="form-control" name="quantity" type="number" min="1" required></div><div class="form-group"><label>Received date</label><input class="form-control" name="received_date" type="date" value="<?=date('Y-m-d')?>"></div><div class="form-group"><label>Expiry date</label><input class="form-control" name="expiry_date" type="date"></div><div class="form-group"><label>Notes</label><input class="form-control" name="notes"></div></div><p><button class="btn btn-primary">Save Batch</button></p></form></div><div class="panel"><div class="panel-head"><h2>Batch Register</h2></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Batch</th><th>Batch Qty</th><th>Received</th><th>Expiry</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):$expired=$r['expiry_date']&&$r['expiry_date']<date('Y-m-d');$soon=$r['expiry_date']&&$r['expiry_date']>=date('Y-m-d')&&$r['expiry_date']<=date('Y-m-d',strtotime('+30 days'));?><tr><td><?=e($r['product_name'])?></td><td><?=e($r['sku'])?></td><td><?=e($r['batch_no'])?></td><td><?=$r['quantity']?></td><td><?=e($r['received_date'])?></td><td><?=e($r['expiry_date']??'—')?></td><td><?php if($expired):?><span class="badge red">Expired</span><?php elseif($soon):?><span class="badge amber">Expires within 30 days</span><?php else:?><span class="badge green">OK</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No batches registered.</td></tr><?php endif;?></tbody></table></div></div><?php include '_footer.php';?>